      "arFull": "هُوَ الَّذِیْ خَلَقَكُمْ مِّنْ طِیْنٍ ثُمَّ قَضٰۤی اَجَلًا ؕ وَاَجَلٌ مُّسَمًّی عِنْدَهٗ ثُمَّ اَنْتُمْ تَمْتَرُوْنَ ۟",
