      "number": 87,
      "arFull": "وَمِنْ اٰبَآىِٕهِمْ وَذُرِّیّٰتِهِمْ وَاِخْوَانِهِمْ ۚ وَاجْتَبَیْنٰهُمْ وَهَدَیْنٰهُمْ اِلٰی صِرَاطٍ مُّسْتَقِیْمٍ ۟",
