      "arFull": "اِتَّبِعْ مَاۤ اُوْحِیَ اِلَیْكَ مِنْ رَّبِّكَ ۚ لَاۤ اِلٰهَ اِلَّا هُوَ ۚ وَاَعْرِضْ عَنِ الْمُشْرِكِیْنَ ۟",
