      "arFull": "وَذَرُوْا ظَاهِرَ الْاِثْمِ وَبَاطِنَهٗ ؕ اِنَّ الَّذِیْنَ یَكْسِبُوْنَ الْاِثْمَ سَیُجْزَوْنَ بِمَا كَانُوْا یَقْتَرِفُوْنَ ۟",
